const req = $('When Called').first().json;
const config = $input.first().json.data;
const L = config.limits;
const errors = [];
const clean = value => (typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '');

const topic = clean(req.topic);
if (!topic) {
  errors.push('topic is required');
} else if (topic.length < L.topic_min_chars || topic.length > L.topic_max_chars) {
  errors.push('topic must be between ' + L.topic_min_chars + ' and ' + L.topic_max_chars + ' characters');
}

const styleIds = Object.keys(config.styles);
const style = clean(req.style).toLowerCase().replace(/[\s-]+/g, '_') || 'auto';
if (style !== 'auto' && !styleIds.includes(style)) {
  errors.push('style must be one of: auto, ' + styleIds.join(', '));
}

const audience = clean(req.audience);
if (audience.length > L.audience_max_chars) {
  errors.push('audience must be at most ' + L.audience_max_chars + ' characters');
}
const tone = clean(req.tone);
if (tone.length > L.tone_max_chars) {
  errors.push('tone must be at most ' + L.tone_max_chars + ' characters');
}

let wordTarget = config.quality.default_word_target;
if (req.word_target !== undefined && req.word_target !== null && req.word_target !== '') {
  const n = Number(req.word_target);
  if (!Number.isInteger(n) || n < L.word_target_min || n > L.word_target_max) {
    errors.push('word_target must be a whole number between ' + L.word_target_min + ' and ' + L.word_target_max);
  } else {
    wordTarget = n;
  }
}

const imageAspect = clean(req.image_aspect) || L.image_aspects[0];
if (!L.image_aspects.includes(imageAspect)) {
  errors.push('image_aspect must be one of: ' + L.image_aspects.join(', '));
}

// Fault injection (only when config.flags.allow_fault_injection is true).
const requested = req.simulate && typeof req.simulate === 'object' ? req.simulate : {};
const allowFaults = config.flags.allow_fault_injection === true;
const simulate = {
  text_primary_fail: allowFaults && requested.text_primary_fail === true,
  image_primary_fail: allowFaults && requested.image_primary_fail === true,
  fatal: allowFaults && requested.fatal === true
};
if (simulate.fatal) {
  throw new Error('Simulated fatal error (fault injection: simulate.fatal)');
}

const startedAt = Number(req.received_at) || Date.now();
const runId = 'cg-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    valid: errors.length === 0,
    errors,
    config,
    run: {
      run_id: runId,
      source: clean(req.source) || 'api',
      request_id: clean(req.request_id) || null,
      started_at: startedAt,
      deadline_at: startedAt + config.budget.total_ms,
      output_dir: 'outputs',
      container_dir: '/home/node/.n8n-files/outputs',
      simulate
    },
    request: { topic, style_requested: style, audience, tone, word_target: wordTarget, image_aspect: imageAspect }
  }
}];

const STOP = new Set('a an and are as at be by for from how in into is it its of on or that the this to vs what when where which who why will with your our their about after before over under between new now than more most'.split(' '));
const tokens = text => String(text || '')
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(word => word.length > 2 && !STOP.has(word))
  .map(word => word.replace(/ies$/, 'y').replace(/([^s])s$/, '$1'));
const jaccard = (a, b) => {
  const A = new Set(a);
  const B = new Set(b);
  if (!A.size || !B.size) return 0;
  let shared = 0;
  for (const x of A) if (B.has(x)) shared += 1;
  return shared / (A.size + B.size - shared);
};

const base = $('Validate Request').first().json;
const config = base.config;
const D = config.diversity;
const P = config.pools;
const request = base.request;
const run = base.run;
// Finished runs plus recent 'planned' reservations, so runs that start at the same time
// (batch waves) also steer away from each other.
const history = $input.all()
  .map(item => item.json)
  .filter(row => row && row.run_id && (
    ['success', 'needs_review', 'partial'].includes(row.status) ||
    (row.status === 'planned' && Date.now() - Date.parse(row.createdAt) < 10 * 60 * 1000)
  ));

// Seeded PRNG (FNV-1a + mulberry32): the same run_id and history always replay the same plan.
let state = 2166136261;
for (let i = 0; i < run.run_id.length; i += 1) {
  state = Math.imul(state ^ run.run_id.charCodeAt(i), 16777619);
}
const seed = state >>> 0;
const random = () => {
  state = (state + 0x6D2B79F5) | 0;
  let t = Math.imul(state ^ (state >>> 15), 1 | state);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

const topicTokens = tokens(request.topic);
const topicKey = Array.from(new Set(topicTokens)).sort().join(' ');
const related = history.filter(row => jaccard(topicTokens, String(row.topic_key || '').split(' ').filter(Boolean)) >= D.related_topic_similarity);
const previous = history[0] || null;
const lastRelated = related[0] || null;

// Weighted draw. Choices of the previous run and of the latest run on a related topic are
// excluded, older related-topic choices are down-weighted, and format-suited visuals are boosted.
const choose = (options, field, boosted) => {
  const usedForRelated = new Set(related.map(row => row[field]).filter(Boolean));
  const weighted = options.map(option => {
    const id = typeof option === 'string' ? option : option.id;
    let weight = 1;
    if ((previous && previous[field] === id) || (lastRelated && lastRelated[field] === id)) weight = 0;
    if (usedForRelated.has(id)) weight *= D.used_weight;
    if (boosted && boosted.includes(id)) weight *= D.affinity_weight;
    return { option, id, weight };
  });
  const total = weighted.reduce((sum, entry) => sum + entry.weight, 0);
  let ticket = random() * total;
  for (const entry of weighted) {
    if (entry.weight === 0) continue;
    ticket -= entry.weight;
    if (ticket <= 0) return entry;
  }
  return weighted.filter(entry => entry.weight > 0).pop() || weighted[0];
};

const style = request.style_requested === 'auto'
  ? choose(Object.keys(config.styles), 'style').id
  : request.style_requested;
const styleConfig = config.styles[style];
const angle = choose(P.angles, 'angle').option;
const hook = choose(P.hooks, 'hook').option;
const audience = request.audience
  ? { id: 'custom', text: request.audience }
  : choose(P.audiences, 'audience').option;
const visual = {
  style: choose(P.visual_styles, 'visual_style', styleConfig.visual_affinity).id,
  composition: choose(P.compositions, 'composition').id,
  palette: choose(P.palettes, 'palette').id,
  lighting: choose(P.lighting, 'lighting').id
};

return [{
  json: {
    ctx: {
      run,
      request,
      plan: {
        style,
        style_source: request.style_requested === 'auto' ? 'auto' : 'requested',
        angle,
        hook,
        audience,
        tone: request.tone || styleConfig.tone,
        visual,
        topic_key: topicKey,
        history_considered: history.length,
        related_runs: related.length,
        avoid_titles: related.map(row => row.title).filter(Boolean).slice(0, D.avoid_list_size),
        seed
      },
      brief: null,
      brief_attempts: 0,
      novelty: null,
      novelty_retry: null,
      article: null,
      image: null,
      image_prompt: null,
      calls: [],
      failure: null
    }
  }
}];

// The first pass arrives from Reserve Plan (the inserted row); retries arrive with ctx from Check Brief.
const ctx = $json.ctx || $('Plan Variation').first().json.ctx;
const config = $('Validate Request').first().json.config;
const M = config.models.text;
const style = config.styles[ctx.plan.style];
const plan = ctx.plan;
const lines = [
  'Plan one ' + style.label.toLowerCase() + ' on this topic: "' + ctx.request.topic + '".',
  '',
  'Purpose of this format: ' + style.purpose + '.',
  'Required structure (section headings must follow it):',
  ...style.structure.map(item => '- ' + item),
  'Format rules:',
  ...style.rules.map(rule => '- ' + rule),
  '',
  'Audience: ' + plan.audience.text + '.',
  'Tone: ' + plan.tone + '.',
  'Angle that must shape the whole piece: ' + plan.angle.text + '.',
  'Opening approach: ' + plan.hook.text + '.',
  'Target length: about ' + ctx.request.word_target + ' words.'
];
if (plan.avoid_titles.length) {
  lines.push('', 'Recent pieces on related topics used these titles. Choose a clearly different framing and title:');
  plan.avoid_titles.forEach(title => lines.push('- ' + title));
}
if (ctx.novelty_retry) {
  lines.push('', 'Your previous plan was titled "' + ctx.novelty_retry.previous_title + '", which is too close to an earlier piece. Use a distinctly different title and section structure.');
}
lines.push('', 'The image concept must describe one concrete scene that fits this piece, without text, logos or recognizable real people.');

const schema = {
  type: 'object',
  properties: {
    title: { type: 'string', description: 'Specific, compelling headline of at most 90 characters' },
    meta_description: { type: 'string', description: 'Search snippet of 140 to 160 characters' },
    thesis: { type: 'string', description: 'The core message in one sentence' },
    sections: {
      type: 'array',
      minItems: 3,
      maxItems: 8,
      items: {
        type: 'object',
        properties: {
          heading: { type: 'string', description: 'Section heading exactly as it should appear in the article' },
          key_points: { type: 'array', minItems: 1, maxItems: 4, items: { type: 'string' } }
        },
        required: ['heading', 'key_points']
      }
    },
    keywords: { type: 'array', minItems: 3, maxItems: 6, items: { type: 'string' } },
    image_concept: {
      type: 'object',
      properties: {
        subject: { type: 'string', description: 'Main subject of the image' },
        setting: { type: 'string', description: 'Where the scene takes place' },
        details: { type: 'string', description: 'Two or three concrete visual details' },
        mood: { type: 'string', description: 'Emotional tone of the image' }
      },
      required: ['subject', 'setting', 'details', 'mood']
    }
  },
  required: ['title', 'meta_description', 'thesis', 'sections', 'keywords', 'image_concept']
};

return {
  json: {
    purpose: 'brief',
    models: { primary: M.primary, fallback: M.fallback },
    system: 'You are a senior editor who plans original, specific and accurate content. You never invent statistics, quotes or sources.',
    prompt: lines.join('\n'),
    response_schema: schema,
    temperature: 1,
    max_output_tokens: 4096,
    thinking_level: M.thinking_level,
    timeout_ms: M.timeouts_ms.brief,
    deadline_at: ctx.run.deadline_at,
    pricing: config.pricing_usd_per_million_tokens,
    simulate_primary_fail: ctx.run.simulate.text_primary_fail,
    passthrough: ctx
  }
};

const v = $input.first().json;
return [{
  json: {
    status: 'rejected',
    http_status: 400,
    run_id: v.run.run_id,
    errors: v.errors,
    message: 'Invalid request: ' + v.errors.join('; ')
  }
}];

const STOP = new Set('a an and are as at be by for from how in into is it its of on or that the this to vs what when where which who why will with your our their about after before over under between new now than more most'.split(' '));
const tokens = text => String(text || '')
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(word => word.length > 2 && !STOP.has(word))
  .map(word => word.replace(/ies$/, 'y').replace(/([^s])s$/, '$1'));
const jaccard = (a, b) => {
  const A = new Set(a);
  const B = new Set(b);
  if (!A.size || !B.size) return 0;
  let shared = 0;
  for (const x of A) if (B.has(x)) shared += 1;
  return shared / (A.size + B.size - shared);
};

const res = $json;
const ctx = res.passthrough;
const config = $('Validate Request').first().json.config;
ctx.calls.push({ purpose: 'brief', ok: res.ok, model: res.model, fallback_used: res.fallback_used, latency_ms: res.latency_ms, cost_usd: res.cost_usd, usage: res.usage, error: res.error });
ctx.brief_attempts += 1;

if (!res.ok) {
  ctx.failure = { stage: 'brief', message: res.error };
  return { json: { ctx, next: 'fail' } };
}

const brief = res.data || {};
const sections = Array.isArray(brief.sections) ? brief.sections.filter(s => s && s.heading) : [];
const complete = Boolean(brief.title && brief.thesis && sections.length >= 3 && brief.image_concept);
if (!complete) {
  if (ctx.brief_attempts < 2) {
    return { json: { ctx, next: 'retry' } };
  }
  ctx.failure = { stage: 'brief', message: 'The brief was missing required fields twice' };
  return { json: { ctx, next: 'fail' } };
}

// Novelty gate: compare the new title with recent titles on related topics; regenerate once if too close.
const titleTokens = tokens(brief.title);
const similarity = Math.max(0, ...ctx.plan.avoid_titles.map(title => jaccard(titleTokens, tokens(title))));
if (similarity > config.quality.novelty_max_similarity && ctx.brief_attempts < 2) {
  ctx.novelty_retry = { previous_title: brief.title, similarity: Number(similarity.toFixed(2)) };
  return { json: { ctx, next: 'retry' } };
}

const title = String(brief.title).trim();
ctx.brief = {
  title,
  slug: title.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-+$/, ''),
  meta_description: String(brief.meta_description || '').trim(),
  thesis: String(brief.thesis).trim(),
  sections: sections.map(s => ({ heading: String(s.heading).trim(), key_points: (s.key_points || []).map(String) })),
  keywords: (brief.keywords || []).map(String),
  image_concept: brief.image_concept
};
ctx.novelty = {
  score: Number((1 - similarity).toFixed(2)),
  max_title_similarity: Number(similarity.toFixed(2)),
  compared_with: ctx.plan.avoid_titles.length,
  regenerated: Boolean(ctx.novelty_retry)
};
return { json: { ctx, next: 'write' } };

const item = $input.first();
const fromImage = item.json.passthrough !== undefined;
const ctx = fromImage ? item.json.passthrough : item.json.ctx;
const now = Date.now();

if (fromImage) {
  const r = item.json;
  ctx.calls.push({ purpose: 'image', ok: r.ok, model: r.model, fallback_used: r.fallback_used, latency_ms: r.latency_ms, cost_usd: r.cost_usd, usage: r.usage, error: r.error });
  ctx.image = { ok: r.ok, model: r.model, fallback_used: r.fallback_used, mime_type: r.mime_type, file_extension: r.file_extension, bytes: r.bytes, error: r.error };
}

const { run, request, plan, brief, article, image } = ctx;
let status = 'success';
if (ctx.failure || !article) status = 'failed';
else if (!article.passed) status = 'needs_review';
else if (!image || !image.ok) status = 'partial';

const warnings = [];
if (article) {
  if (!article.passed) warnings.push('Quality checks failing: ' + article.checks.filter(c => !c.passed).map(c => c.id).join(', '));
  article.notes.forEach(note => warnings.push(note));
  if (!image || !image.ok) warnings.push('Image unavailable: ' + (image && image.error ? image.error : 'not generated'));
}

const spent = purposes => ctx.calls.filter(c => purposes.includes(c.purpose)).reduce((sum, c) => sum + (c.latency_ms || 0), 0);
const timings = { brief: spent(['brief']), write: spent(['article', 'revision']), image: spent(['image']), total: now - run.started_at };
const costUsd = Number(ctx.calls.reduce((sum, c) => sum + (c.cost_usd || 0), 0).toFixed(4));
const textCalls = ctx.calls.filter(c => c.purpose !== 'image' && c.ok);
const textModel = textCalls.length ? textCalls[textCalls.length - 1].model : null;
const fallbackUsed = ctx.calls.some(c => c.fallback_used);
const imageFile = image && image.ok ? run.run_id + '.' + image.file_extension : null;
const files = {
  article: article && brief ? run.output_dir + '/' + run.run_id + '.md' : null,
  image: imageFile ? run.output_dir + '/' + imageFile : null,
  metadata: run.output_dir + '/' + run.run_id + '.json'
};

let articleMarkdown = null;
let fileMarkdown = null;
if (article && brief) {
  articleMarkdown = '# ' + brief.title + '\n\n' + article.markdown + '\n';
  const alt = String((brief.image_concept && brief.image_concept.subject) || brief.title).replace(/[\[\]]/g, '');
  fileMarkdown = [
    '---',
    'title: ' + JSON.stringify(brief.title),
    'slug: ' + brief.slug,
    'description: ' + JSON.stringify(brief.meta_description),
    'style: ' + plan.style,
    'audience: ' + JSON.stringify(plan.audience.text),
    'keywords: ' + JSON.stringify(brief.keywords),
    'word_count: ' + article.word_count,
    'status: ' + status,
    'run_id: ' + run.run_id,
    'generated_at: ' + new Date(now).toISOString(),
    '---',
    '',
    '# ' + brief.title,
    '',
    imageFile ? '![' + alt + '](' + imageFile + ')\n' : '',
    article.markdown,
    ''
  ].join('\n');
}

const result = {
  status,
  http_status: status === 'failed' ? 502 : 200,
  run_id: run.run_id,
  topic: request.topic,
  style: plan.style,
  title: brief ? brief.title : null,
  slug: brief ? brief.slug : null,
  meta_description: brief ? brief.meta_description : null,
  word_count: article ? article.word_count : 0,
  article_markdown: articleMarkdown,
  image: {
    status: image ? (image.ok ? 'generated' : 'failed') : 'skipped',
    path: files.image,
    model: image && image.ok ? image.model : null,
    fallback_used: Boolean(image && image.fallback_used),
    aspect_ratio: request.image_aspect,
    prompt: ctx.image_prompt,
    error: image && !image.ok ? image.error : null
  },
  diversity: {
    style_source: plan.style_source,
    angle: plan.angle.id,
    hook: plan.hook.id,
    audience: plan.audience.text,
    visual: plan.visual,
    history_considered: plan.history_considered,
    related_runs: plan.related_runs,
    novelty_score: ctx.novelty ? ctx.novelty.score : null,
    seed: plan.seed
  },
  quality: article ? { passed: article.passed, revisions: article.revisions, checks: article.checks, rounds: article.rounds || [] } : null,
  warnings,
  models: { text: textModel, image: image && image.ok ? image.model : null, fallback_used: fallbackUsed },
  cost_usd: costUsd,
  timings_ms: timings,
  files,
  error: ctx.failure ? ctx.failure.stage + ': ' + ctx.failure.message : null
};

const metadata = Object.assign({}, result, {
  generated_at: new Date(now).toISOString(),
  source: run.source,
  request_id: run.request_id,
  request,
  plan,
  brief,
  novelty: ctx.novelty,
  simulate: run.simulate,
  calls: ctx.calls
});
delete metadata.article_markdown;
delete metadata.http_status;

const log = {
  run_id: run.run_id,
  source: run.source,
  status,
  topic: request.topic,
  topic_key: plan.topic_key,
  style: plan.style,
  style_requested: request.style_requested,
  angle: plan.angle.id,
  hook: plan.hook.id,
  audience: plan.audience.id,
  tone: request.tone || null,
  title: brief ? brief.title : null,
  slug: brief ? brief.slug : null,
  visual_style: plan.visual.style,
  composition: plan.visual.composition,
  palette: plan.visual.palette,
  lighting: plan.visual.lighting,
  word_count: article ? article.word_count : 0,
  revisions: article ? article.revisions : 0,
  quality_passed: article ? article.passed : false,
  novelty_score: ctx.novelty ? ctx.novelty.score : null,
  text_model: textModel,
  image_model: image && image.ok ? image.model : null,
  fallback_used: fallbackUsed,
  duration_ms: timings.total,
  cost_usd: costUsd,
  article_path: files.article,
  error: result.error
};

const out = { json: { result, metadata, log, file_markdown: fileMarkdown, image_file: imageFile, run_id: run.run_id, container_dir: run.container_dir } };
if (imageFile && item.binary && item.binary.image) {
  out.binary = { image: item.binary.image };
}
return [out];

const res = $json;
const ctx = res.passthrough;
const config = $('Validate Request').first().json.config;
const Q = config.quality;
const rules = config.styles[ctx.plan.style].checks || {};
ctx.calls.push({ purpose: res.purpose, ok: res.ok, model: res.model, fallback_used: res.fallback_used, latency_ms: res.latency_ms, cost_usd: res.cost_usd, usage: res.usage, error: res.error });
const previous = ctx.article;

if (!res.ok) {
  if (previous) {
    previous.notes.push('A revision failed, so the previous draft was kept: ' + res.error);
    previous.issues = [];
    return { json: { ctx, next: 'illustrate' } };
  }
  ctx.failure = { stage: 'write', message: res.error };
  return { json: { ctx, next: 'fail' } };
}

// Normalise: drop code fences and a leading H1 (the title is rendered separately).
const markdown = String(res.text)
  .replace(/^\x60{3}[a-z]*\s*\n/i, '')
  .replace(/\n\x60{3}\s*$/, '')
  .trim()
  .replace(/^#\s+[^\n]*\n+/, '')
  .trim();

const countWords = text => (text
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/^\s*(?:[-*+]|\d+[.)])\s+/gm, '')
  .match(/[A-Za-z0-9][A-Za-z0-9'’-]*/g) || []).length;
const wordCount = countWords(markdown);
const lines = markdown.split('\n');
const headings = lines
  .filter(line => /^##\s+/.test(line))
  .map(line => line.replace(/^##\s+/, '').trim());
// Paragraphs: blank out heading lines, split on blank lines, skip list blocks.
const paragraphs = lines
  .map(line => (/^#{1,6}\s/.test(line.trim()) ? '' : line))
  .join('\n')
  .split(/\n\s*\n/)
  .map(block => block.trim())
  .filter(block => block && !/^(?:[-*+]|\d+[.)])\s/.test(block));
const longParagraphs = paragraphs.filter(block => countWords(block) > Q.max_paragraph_words).length;
const lower = markdown.toLowerCase();
const banned = Q.banned_phrases.filter(phrase => lower.includes(phrase.toLowerCase()));
const hasLinks = /https?:\/\/|www\.|\]\(/i.test(markdown);

const checks = [];
const issues = [];
const check = (id, passed, detail, fix) => {
  checks.push({ id, passed, detail });
  if (!passed) issues.push(fix);
};
const target = ctx.request.word_target;
check('word_count', wordCount >= Q.min_words && wordCount <= Q.max_words,
  wordCount + ' words (allowed ' + Q.min_words + '-' + Q.max_words + ')',
  wordCount < Q.min_words
    ? 'It has ' + wordCount + ' words; expand it to about ' + target + ' by deepening the existing sections with concrete examples.'
    : 'It has ' + wordCount + ' words; tighten it to about ' + target + ' without dropping any section.');
check('sections', headings.length >= Q.min_h2_sections,
  headings.length + ' ## sections (min ' + Q.min_h2_sections + ')',
  'Organise the piece into at least ' + Q.min_h2_sections + ' sections with ## headings.');
check('paragraph_length', longParagraphs === 0,
  longParagraphs + ' paragraphs over ' + Q.max_paragraph_words + ' words',
  'Split every paragraph longer than ' + Q.max_paragraph_words + ' words.');
check('banned_phrases', banned.length === 0,
  banned.length ? 'found: ' + banned.join(', ') : 'none found',
  'Remove these phrases: ' + banned.join(', ') + '.');
check('no_links', !hasLinks, hasLinks ? 'contains links' : 'no links', 'Remove all links and URLs.');
if (rules.min_steps) {
  const steps = headings.filter(h => /^step\s+\d+/i.test(h)).length;
  check('steps', steps >= rules.min_steps, steps + ' "Step N" sections (min ' + rules.min_steps + ')',
    'Present the procedure as at least ' + rules.min_steps + ' ## sections titled "Step N: ...".');
}
if (rules.min_numbered_h2) {
  const items = headings.filter(h => /^\d+[.)]\s/.test(h)).length;
  check('numbered_items', items >= rules.min_numbered_h2, items + ' numbered items (min ' + rules.min_numbered_h2 + ')',
    'Present at least ' + rules.min_numbered_h2 + ' items as numbered ## headings such as "## 1. ...".');
}
if (rules.heading_keywords_any) {
  const found = headings.some(h => rules.heading_keywords_any.some(k => h.toLowerCase().includes(k)));
  check('required_section', found, found ? 'present' : 'missing',
    'Add a ## section whose heading includes one of: ' + rules.heading_keywords_any.join(', ') + '.');
}

const passed = checks.every(c => c.passed);
const revisions = previous ? previous.revisions + 1 : 0;
const rounds = (previous ? previous.rounds : []).concat([{ draft: revisions, word_count: wordCount, failed: checks.filter(c => !c.passed).map(c => c.id) }]);
ctx.article = { markdown, word_count: wordCount, headings, checks, issues, passed, revisions, rounds, notes: previous ? previous.notes : [] };

let next = 'illustrate';
if (!passed) {
  if (revisions >= Q.max_revisions) {
    ctx.article.notes.push('Checks still failing after ' + revisions + ' revisions.');
  } else if (Date.now() - ctx.run.started_at > config.budget.revision_cutoff_ms) {
    ctx.article.notes.push('Revision skipped to stay within the time budget.');
  } else {
    next = 'revise';
  }
}
return { json: { ctx, next } };

const ctx = $json.ctx;
const config = $('Validate Request').first().json.config;
const M = config.models.image;
const concept = ctx.brief.image_concept || {};
const visual = ctx.plan.visual;
const clause = value => String(value || '').trim().replace(/[.\s]+$/, '');
const article = /^[aeiou]/i.test(visual.style) ? 'an ' : 'a ';
const prompt = [
  'Create ' + article + visual.style + ' image to accompany an article titled "' + ctx.brief.title + '".',
  'Subject: ' + clause(concept.subject) + '.',
  'Setting: ' + clause(concept.setting) + '.',
  concept.details ? 'Details: ' + clause(concept.details) + '.' : '',
  'Mood: ' + clause(concept.mood) + '.',
  'Composition: ' + visual.composition + '.',
  'Color palette: ' + visual.palette + '.',
  'Lighting: ' + visual.lighting + '.',
  'Do not include any text, letters, numbers, captions, signage, logos, watermarks or brand marks. Any vehicles or products must be unbranded. No recognizable real people.'
].filter(Boolean).join('\n');
ctx.image_prompt = prompt;
return {
  json: {
    purpose: 'image',
    models: { primary: M.primary, fallback: M.fallback },
    prompt,
    aspect_ratio: ctx.request.image_aspect,
    image_size: M.image_size,
    timeout_ms: M.timeout_ms,
    deadline_at: ctx.run.deadline_at,
    pricing: config.pricing_usd_per_million_tokens,
    simulate_primary_fail: ctx.run.simulate.image_primary_fail,
    passthrough: ctx
  }
};

const fin = $input.first();
const f = fin.json;
const asFile = (text, mimeType, fileName) => ({
  data: Buffer.from(text, 'utf8').toString('base64'),
  mimeType,
  fileName,
  fileExtension: fileName.split('.').pop()
});
const base = f.container_dir + '/' + f.run_id;
const files = [];
if (f.file_markdown) {
  files.push({ json: { kind: 'article', path: base + '.md' }, binary: { data: asFile(f.file_markdown, 'text/markdown', f.run_id + '.md') } });
}
if (f.image_file && fin.binary && fin.binary.image) {
  files.push({ json: { kind: 'image', path: f.container_dir + '/' + f.image_file }, binary: { data: fin.binary.image } });
}
files.push({ json: { kind: 'metadata', path: base + '.json' }, binary: { data: asFile(JSON.stringify(f.metadata, null, 2), 'application/json', f.run_id + '.json') } });
return files;

const fin = $('Finalize Run').first();
const out = { json: fin.json.result };
if (fin.binary && fin.binary.image) {
  out.binary = { image: fin.binary.image };
}
return [out];
